/// <summary>
/// UPSPricingAttribute of table <c>MCRInventTable</c> field SellStartDate.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Product, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeMCRInventTableSellStartDate extends UPSPricingAttributeMCRInventTable implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(MCRInventTable, SellStartDate);
}

public Set getAllowedValues()
{   
    MCRInventTable  mcrInventTable;
    var             ret = new Set(Types::Date);

    while select SellStartDate from mcrInventTable
        group by SellStartDate
    {
        if (!ret.in(mcrInventTable.SellStartDate))
        {
            ret.add(mcrInventTable.SellStartDate);
        }
    }

    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(MCRInventTable, SellStartDate));
    qbr.value(queryValue(_value));
}
